INSERT INTO articles (
  title, slug, excerpt, content_json, content_html, article_type, status, subject_id, topic_id, author_id, published_at, seo_title, meta_description, robots, reading_minutes, created_at, updated_at
) VALUES (
  'Glycolysis: Complete Study Notes',
  'glycolysis',
  'Glycolysis notes covering the ten steps with enzymes, the investment and payoff phases, energetics, regulation, fates of pyruvate, and clinical correlations including LDH and lactic acidosis.',
  '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Overview"}]},{"type":"paragraph","content":[{"type":"text","text":"These notes split glycolysis into its investment and payoff phases, tabulate every enzyme with the regulated steps flagged, tally the energetics under aerobic and anaerobic conditions, and finish with the clinical correlations — LDH, lactic acidosis and pyruvate kinase deficiency."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Introduction"}]},{"type":"paragraph","content":[{"type":"text","text":"Glycolysis is the first pathway every biochemistry course teaches, and the one every examiner returns to. It is the only energy pathway that works in every cell of the body — including red blood cells, which have no mitochondria — because it runs in the cytosol and needs no oxygen. The pathway splits neatly into two halves that make memorization manageable: an "},{"type":"text","text":"investment phase","marks":[{"type":"bold"}]},{"type":"text","text":" that spends ATP to trap and split glucose, and a "},{"type":"text","text":"payoff phase","marks":[{"type":"bold"}]},{"type":"text","text":" that harvests ATP from the two three-carbon fragments."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Investment Phase (Steps 1–5)"}]},{"type":"paragraph","content":[{"type":"text","text":"One glucose is phosphorylated, isomerized, phosphorylated again, and split into two three-carbon sugars:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hexokinase / glucokinase","marks":[{"type":"bold"}]},{"type":"text","text":" — glucose to glucose-6-phosphate; **ATP is"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"consumed**. Hexokinase is everywhere with low Km and product inhibition by    glucose-6-phosphate; glucokinase is liver and pancreatic beta-cell    specific with high Km and no product inhibition."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phosphoglucose isomerase","marks":[{"type":"bold"}]},{"type":"text","text":" — glucose-6-phosphate to"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"fructose-6-phosphate."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phosphofructokinase-1 (PFK-1)","marks":[{"type":"bold"}]},{"type":"text","text":" — fructose-6-phosphate to"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"fructose-1,6-bisphosphate; "},{"type":"text","text":"ATP consumed","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"rate-limiting step","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Aldolase","marks":[{"type":"bold"}]},{"type":"text","text":" — cleaves fructose-1,6-bisphosphate into"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"dihydroxyacetone phosphate and glyceraldehyde-3-phosphate."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Triose phosphate isomerase","marks":[{"type":"bold"}]},{"type":"text","text":" — converts dihydroxyacetone phosphate to"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"glyceraldehyde-3-phosphate, so both halves feed forward."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Payoff Phase (Steps 6–10)"}]},{"type":"paragraph","content":[{"type":"text","text":"Each glyceraldehyde-3-phosphate (two per glucose) now pays back:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Glyceraldehyde-3-phosphate dehydrogenase","marks":[{"type":"bold"}]},{"type":"text","text":" — oxidation and"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"phosphorylation to 1,3-bisphosphoglycerate, reducing "},{"type":"text","text":"NAD+ to NADH","marks":[{"type":"bold"}]},{"type":"text","text":".    This is the only oxidation step of glycolysis."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phosphoglycerate kinase","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"ATP produced","marks":[{"type":"bold"}]},{"type":"text","text":" by substrate-level"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"phosphorylation."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phosphoglycerate mutase","marks":[{"type":"bold"}]},{"type":"text","text":" — 3-phosphoglycerate to 2-phosphoglycerate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enolase","marks":[{"type":"bold"}]},{"type":"text","text":" — dehydration to phosphoenolpyruvate. *Fluoride inhibits"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"enolase — the reason glucose samples go into fluoride tubes.*"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pyruvate kinase","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"ATP produced","marks":[{"type":"bold"}]},{"type":"text","text":"; substrate-level phosphorylation"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"yielding pyruvate and ending the pathway."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Step"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Enzyme"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Cofactor / energy"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Regulated?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Hexokinase / glucokinase"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ATP → ADP"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes — inhibited by G6P (hexokinase)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"3"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"PFK-1"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ATP → ADP"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes — rate-limiting; AMP, F-2,6-BP activate; ATP, citrate inhibit"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"6"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"GAPDH"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"NAD+ → NADH"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"No"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"7"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Phosphoglycerate kinase"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ATP produced"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"No"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"10"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Pyruvate kinase"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ATP produced"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes — activated by F-1,6-BP; inhibited by ATP and alanine"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Energetics"}]},{"type":"paragraph","content":[{"type":"text","text":"Per molecule of glucose (which yields two three-carbon units):"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Invested:","marks":[{"type":"bold"}]},{"type":"text","text":" 2 ATP (steps 1 and 3)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Produced:","marks":[{"type":"bold"}]},{"type":"text","text":" 4 ATP (steps 7 and 10, running twice each)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Net anaerobically: 2 ATP","marks":[{"type":"bold"}]},{"type":"text","text":", plus 2 NADH that are consumed in reducing"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"pyruvate to lactate."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Aerobically:","marks":[{"type":"bold"}]},{"type":"text","text":" the 2 NADH enter the mitochondria through shuttles —"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"the malate-aspartate shuttle yields about 2.5 ATP each, the   glycerol-3-phosphate shuttle about 1.5 each — giving roughly "},{"type":"text","text":"7 ATP   equivalents from glycolysis alone","marks":[{"type":"bold"}]},{"type":"text","text":" before the TCA cycle and oxidative   phosphorylation add their share."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Worked exam framing"}]},{"type":"paragraph","content":[{"type":"text","text":"An MCQ asks: "},{"type":"text","text":"a patient in cardiogenic shock has tissue hypoxia; what is the net ATP per glucose from glycolysis, and what accumulates?","marks":[{"type":"italic"}]},{"type":"text","text":" Answer: net 2 ATP, and lactate accumulates because NADH cannot be oxidized by the electron transport chain, so LDH regenerates NAD+ at pyruvate''s expense — the biochemistry of lactic acidosis (Type A, due to tissue hypoxia)."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Fates of Pyruvate"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Oxidative decarboxylation to acetyl-CoA","marks":[{"type":"bold"}]},{"type":"text","text":" by the pyruvate"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"dehydrogenase complex — aerobic, mitochondrial, irreversible; the link to    the TCA cycle."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reduction to lactate","marks":[{"type":"bold"}]},{"type":"text","text":" by LDH — anaerobic muscle, red cells, and the"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cori cycle with the liver."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Carboxylation to oxaloacetate","marks":[{"type":"bold"}]},{"type":"text","text":" by pyruvate carboxylase — the first"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"committed step of gluconeogenesis and an anaplerotic refill for the TCA    cycle."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Transamination to alanine","marks":[{"type":"bold"}]},{"type":"text","text":" — the glucose-alanine cycle between muscle"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"and liver."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In yeast, decarboxylation to acetaldehyde and ethanol — fermentation,"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"tested as general biochemistry rather than human."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Regulation: Fed versus Fasting State"}]},{"type":"paragraph","content":[{"type":"text","text":"The three irreversible enzymes let the pathway respond to the body''s fuel state:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hexokinase vs glucokinase","marks":[{"type":"bold"}]},{"type":"text","text":" — hexokinase''s low Km means it works at all"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"times in all tissues; the liver''s glucokinase, with its high Km and its   induction by insulin, only engages when blood glucose is high after a meal.   This is why the liver buffers blood glucose but does not compete for it   when glucose is scarce."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PFK-1 and fructose-2,6-bisphosphate","marks":[{"type":"bold"}]},{"type":"text","text":" — in the fed state, insulin raises"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"fructose-2,6-bisphosphate (through activation of the kinase domain of the   bifunctional PFK-2/FBPase-2 enzyme) and glycolysis accelerates. In   fasting, glucagon shifts the same bifunctional enzyme to its phosphatase   mode, fructose-2,6-bisphosphate falls, PFK-1 slows, and the liver switches   to gluconeogenesis."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pyruvate kinase","marks":[{"type":"bold"}]},{"type":"text","text":" — the liver isoenzyme is phosphorylated and"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"inactivated by the glucagon-driven cAMP cascade, reinforcing the   fasting-state shutdown; the muscle and brain isoenzymes are not   glucagon-sensitive and keep glycolysis running for their own needs."}]},{"type":"paragraph","content":[{"type":"text","text":"The unifying idea for the viva: "},{"type":"text","text":"glycolysis is promoted by insulin and inhibited by glucagon in the liver, but is always allowed to run in the brain and red cells, which cannot burn anything else.","marks":[{"type":"bold"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Clinical Correlations"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"LDH isoenzymes:","marks":[{"type":"bold"}]},{"type":"text","text":" LDH is a tetramer of H and M subunits — LDH-1 (H4)"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"is dominant in heart, LDH-5 (M4) in liver and skeletal muscle. Historically   the LDH-1 greater than LDH-2 \"flipped pattern\" supported myocardial   infarction; today troponin has replaced it, but the isoenzyme logic still   appears in exams."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lactic acidosis:","marks":[{"type":"bold"}]},{"type":"text","text":" Type A from tissue hypoxia (shock, severe asthma,"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"seizures); Type B without hypoxia — metformin in renal failure, alcohol,   mitochondrial disorders. Anion-gap metabolic acidosis with elevated lactate."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pyruvate kinase deficiency:","marks":[{"type":"bold"}]},{"type":"text","text":" chronic haemolytic anaemia; red cells"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"cannot sustain ATP and deformability. Interestingly the blocked distal   pathway shunts intermediates to 2,3-BPG, which raises it and shifts the   oxygen dissociation curve right, easing tissue oxygen delivery."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cancer metabolism — the Warburg effect:","marks":[{"type":"bold"}]},{"type":"text","text":" tumours run glycolysis to"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"lactate even in oxygen, the principle behind PET imaging with   fluorodeoxyglucose, which is trapped intracellularly once phosphorylated by   hexokinase."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Revision Pointers"}]},{"type":"paragraph","content":[{"type":"text","text":"Write the ten enzymes in order before checking the table, then mark the three irreversible steps — those are your regulation questions and the gluconeogenesis bypasses (glucose-6-phosphatase, fructose-1,6-bisphosphatase, PEP carboxykinase plus pyruvate carboxylase). Link the energetics forward to the TCA cycle and backwards to glycogen, and test yourself with the "},{"type":"text","text":"biochemistry practice quiz","marks":[{"type":"link","attrs":{"href":"/practice/quiz/biochemistry/"}}]},{"type":"text","text":". For how the hypoxic heart pays its energy bill, see the "},{"type":"text","text":"cardiac cycle study note","marks":[{"type":"link","attrs":{"href":"/notes/cardiac-cycle/"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Learning objectives"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"List the ten reactions of glycolysis in order with their enzymes"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distinguish the investment phase from the payoff phase energetically"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain the three irreversible, regulated steps and their allosteric modulators"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Calculate the net ATP and NADH yield per glucose under aerobic and anaerobic conditions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Describe the five fates of pyruvate and their physiological contexts"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interpret LDH isoenzymes, lactic acidosis and pyruvate kinase deficiency clinically"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Key terms"}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Glycolysis","marks":[{"type":"bold"}]},{"type":"text","text":" — The cytosolic pathway that converts one glucose molecule to two pyruvate molecules, the central route of carbohydrate catabolism."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Rate-limiting enzyme","marks":[{"type":"bold"}]},{"type":"text","text":" — Phosphofructokinase-1 (PFK-1), the slowest and most tightly controlled enzyme of glycolysis."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Substrate-level phosphorylation","marks":[{"type":"bold"}]},{"type":"text","text":" — ATP production by transfer of a phosphate from a high-energy metabolic intermediate directly to ADP, without the electron transport chain."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Fructose-2,6-bisphosphate","marks":[{"type":"bold"}]},{"type":"text","text":" — The most potent allosteric activator of PFK-1; its level rises with insulin and falls with glucagon."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Cori cycle","marks":[{"type":"bold"}]},{"type":"text","text":" — The lactate shuttle in which muscle anaerobic glycolysis exports lactate to the liver, which reconverts it to glucose."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Lactate dehydrogenase","marks":[{"type":"bold"}]},{"type":"text","text":" — The enzyme that reduces pyruvate to lactate while regenerating NAD+ for continued glycolysis under anaerobic conditions."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Warburg effect","marks":[{"type":"bold"}]},{"type":"text","text":" — The tendency of rapidly dividing tumour cells to ferment glucose to lactate even when oxygen is available."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Pasteur effect","marks":[{"type":"bold"}]},{"type":"text","text":" — The slowing of glycolysis in the presence of oxygen, because oxidative phosphorylation yields far more ATP and suppresses the pathway''s rate."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Important points"}]},{"type":"important","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Glycolysis occurs in the cytosol, needs no oxygen and no mitochondria, and is therefore universal to all cells including mature red cells."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Two steps consume ATP (hexokinase/glucokinase and PFK-1) and two produce it (phosphoglycerate kinase and pyruvate kinase) — per glucose the pathway pays 2 and earns 4 ATP."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only three steps are irreversible — hexokinase, PFK-1 and pyruvate kinase — and these are the regulated steps and the gluconeogenesis bypasses."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PFK-1 is the rate-limiting enzyme; AMP and fructose-2,6-bisphosphate activate it, ATP and citrate inhibit it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The only oxidation step is glyceraldehyde-3-phosphate dehydrogenase, producing 2 NADH per glucose."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anaerobic net yield is 2 ATP per glucose; aerobic yield from glycolysis proper is about 7 ATP equivalent (2 substrate-level plus 2 NADH)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fluoride inhibits enolase, which is why fluoride tubes are used for blood glucose estimation."}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Key formulas"}]},{"type":"keyPoint","content":[{"type":"paragraph","content":[{"type":"text","text":"Glucose + 2 NAD+ + 2 ADP + 2 Pi → 2 Pyruvate + 2 NADH + 2 H+ + 2 ATP + 2 H2O","marks":[{"type":"bold"}]},{"type":"text","text":" — The overall balanced equation of glycolysis to pyruvate."}]}]},{"type":"keyPoint","content":[{"type":"paragraph","content":[{"type":"text","text":"Net ATP (anaerobic) = 4 produced − 2 invested = 2 ATP per glucose","marks":[{"type":"bold"}]},{"type":"text","text":" — The energy yield when pyruvate is reduced to lactate and NADH is recycled internally."}]}]},{"type":"keyPoint","content":[{"type":"paragraph","content":[{"type":"text","text":"Glucose → 2 Lactate + 2 H+ (net 2 ATP)","marks":[{"type":"bold"}]},{"type":"text","text":" — Anaerobic glycolysis overall; the proton production is the biochemical basis of lactic acidosis."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Summary"}]},{"type":"keyPoint","content":[{"type":"paragraph","content":[{"type":"text","text":"Glycolysis is the cytosolic, oxygen-independent conversion of glucose to two pyruvate molecules through ten enzyme-catalysed steps. The first five steps invest 2 ATP to split and phosphorylate the hexose; the payoff phase yields 4 ATP and 2 NADH per glucose, for a net of 2 ATP anaerobically and about 7 ATP equivalent aerobically. Regulation concentrates on the three irreversible enzymes — hexokinase, PFK-1 and pyruvate kinase — with PFK-1 rate-limiting and responsive to the insulin-glucagon axis through fructose-2,6-bisphosphate. Pyruvate then branches to acetyl-CoA, lactate, oxaloacetate or alanine, and the clinical face of the pathway appears as LDH isoenzymes, lactic acidosis, and pyruvate kinase deficiency."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Frequently asked questions"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Why is phosphofructokinase-1 called the rate-limiting enzyme of glycolysis?"}]},{"type":"paragraph","content":[{"type":"text","text":"It catalyses the slowest, essentially irreversible step — fructose-6-phosphate to fructose-1,6-bisphosphate — and it integrates the cell''s energy state: AMP and fructose-2,6-bisphosphate speed it up, while ATP and citrate slow it down. Flux through PFK-1 sets the flux through the whole pathway."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What is the net ATP yield of glycolysis per glucose?"}]},{"type":"paragraph","content":[{"type":"text","text":"Two ATP anaerobically: four produced by substrate-level phosphorylation minus two invested in the hexokinase and PFK-1 steps. Aerobically the 2 NADH add about 5 more ATP equivalents via shuttles, giving roughly 7 ATP equivalent from glycolysis itself, before the pyruvate enters the TCA cycle."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"How does glycolysis continue in the absence of oxygen?"}]},{"type":"paragraph","content":[{"type":"text","text":"Lactate dehydrogenase reduces pyruvate to lactate, oxidizing NADH back to NAD+. This regenerates the NAD+ that glyceraldehyde-3-phosphate dehydrogenase needs, so the payoff phase can keep running and the cell keeps its net 2 ATP."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Why does pyruvate kinase deficiency cause haemolytic anaemia?"}]},{"type":"paragraph","content":[{"type":"text","text":"Mature red blood cells depend entirely on glycolysis for ATP because they have no mitochondria. When pyruvate kinase fails, ATP falls, the red cell cannot maintain its membrane pumps and shape, and it is destroyed in the spleen — a chronic haemolytic anaemia that usually presents in childhood."}]},{"type":"references","attrs":{"items":[{"title":"Harper''s Illustrated Biochemistry","source":"McGraw Hill"},{"title":"Lippincott Illustrated Reviews: Biochemistry","source":"Wolters Kluwer"}]}}]}',
  '<h2>Overview</h2><p>These notes split glycolysis into its investment and payoff phases, tabulate every enzyme with the regulated steps flagged, tally the energetics under aerobic and anaerobic conditions, and finish with the clinical correlations — LDH, lactic acidosis and pyruvate kinase deficiency.</p><h2>Introduction</h2><p>Glycolysis is the first pathway every biochemistry course teaches, and the one every examiner returns to. It is the only energy pathway that works in every cell of the body — including red blood cells, which have no mitochondria — because it runs in the cytosol and needs no oxygen. The pathway splits neatly into two halves that make memorization manageable: an <strong>investment phase</strong> that spends ATP to trap and split glucose, and a <strong>payoff phase</strong> that harvests ATP from the two three-carbon fragments.</p><h2>The Investment Phase (Steps 1–5)</h2><p>One glucose is phosphorylated, isomerized, phosphorylated again, and split into two three-carbon sugars:</p><ol><li><p><strong>Hexokinase / glucokinase</strong> — glucose to glucose-6-phosphate; **ATP is</p></li></ol><p>consumed**. Hexokinase is everywhere with low Km and product inhibition by    glucose-6-phosphate; glucokinase is liver and pancreatic beta-cell    specific with high Km and no product inhibition.</p><ol><li><p><strong>Phosphoglucose isomerase</strong> — glucose-6-phosphate to</p></li></ol><p>fructose-6-phosphate.</p><ol><li><p><strong>Phosphofructokinase-1 (PFK-1)</strong> — fructose-6-phosphate to</p></li></ol><p>fructose-1,6-bisphosphate; <strong>ATP consumed</strong>, <strong>rate-limiting step</strong>.</p><ol><li><p><strong>Aldolase</strong> — cleaves fructose-1,6-bisphosphate into</p></li></ol><p>dihydroxyacetone phosphate and glyceraldehyde-3-phosphate.</p><ol><li><p><strong>Triose phosphate isomerase</strong> — converts dihydroxyacetone phosphate to</p></li></ol><p>glyceraldehyde-3-phosphate, so both halves feed forward.</p><h2>The Payoff Phase (Steps 6–10)</h2><p>Each glyceraldehyde-3-phosphate (two per glucose) now pays back:</p><ol><li><p><strong>Glyceraldehyde-3-phosphate dehydrogenase</strong> — oxidation and</p></li></ol><p>phosphorylation to 1,3-bisphosphoglycerate, reducing <strong>NAD+ to NADH</strong>.    This is the only oxidation step of glycolysis.</p><ol><li><p><strong>Phosphoglycerate kinase</strong> — <strong>ATP produced</strong> by substrate-level</p></li></ol><p>phosphorylation.</p><ol><li><p><strong>Phosphoglycerate mutase</strong> — 3-phosphoglycerate to 2-phosphoglycerate.</p></li><li><p><strong>Enolase</strong> — dehydration to phosphoenolpyruvate. *Fluoride inhibits</p></li></ol><p>enolase — the reason glucose samples go into fluoride tubes.*</p><ol><li><p><strong>Pyruvate kinase</strong> — <strong>ATP produced</strong>; substrate-level phosphorylation</p></li></ol><p>yielding pyruvate and ending the pathway.</p><table><tbody><tr><th><p>Step</p></th><th><p>Enzyme</p></th><th><p>Cofactor / energy</p></th><th><p>Regulated?</p></th></tr><tr><td><p>1</p></td><td><p>Hexokinase / glucokinase</p></td><td><p>ATP → ADP</p></td><td><p>Yes — inhibited by G6P (hexokinase)</p></td></tr><tr><td><p>3</p></td><td><p>PFK-1</p></td><td><p>ATP → ADP</p></td><td><p>Yes — rate-limiting; AMP, F-2,6-BP activate; ATP, citrate inhibit</p></td></tr><tr><td><p>6</p></td><td><p>GAPDH</p></td><td><p>NAD+ → NADH</p></td><td><p>No</p></td></tr><tr><td><p>7</p></td><td><p>Phosphoglycerate kinase</p></td><td><p>ATP produced</p></td><td><p>No</p></td></tr><tr><td><p>10</p></td><td><p>Pyruvate kinase</p></td><td><p>ATP produced</p></td><td><p>Yes — activated by F-1,6-BP; inhibited by ATP and alanine</p></td></tr></tbody></table><h2>Energetics</h2><p>Per molecule of glucose (which yields two three-carbon units):</p><ul><li><p><strong>Invested:</strong> 2 ATP (steps 1 and 3).</p></li><li><p><strong>Produced:</strong> 4 ATP (steps 7 and 10, running twice each).</p></li><li><p><strong>Net anaerobically: 2 ATP</strong>, plus 2 NADH that are consumed in reducing</p></li></ul><p>pyruvate to lactate.</p><ul><li><p><strong>Aerobically:</strong> the 2 NADH enter the mitochondria through shuttles —</p></li></ul><p>the malate-aspartate shuttle yields about 2.5 ATP each, the   glycerol-3-phosphate shuttle about 1.5 each — giving roughly <strong>7 ATP   equivalents from glycolysis alone</strong> before the TCA cycle and oxidative   phosphorylation add their share.</p><h3>Worked exam framing</h3><p>An MCQ asks: <em>a patient in cardiogenic shock has tissue hypoxia; what is the net ATP per glucose from glycolysis, and what accumulates?</em> Answer: net 2 ATP, and lactate accumulates because NADH cannot be oxidized by the electron transport chain, so LDH regenerates NAD+ at pyruvate''s expense — the biochemistry of lactic acidosis (Type A, due to tissue hypoxia).</p><h2>Fates of Pyruvate</h2><ol><li><p><strong>Oxidative decarboxylation to acetyl-CoA</strong> by the pyruvate</p></li></ol><p>dehydrogenase complex — aerobic, mitochondrial, irreversible; the link to    the TCA cycle.</p><ol><li><p><strong>Reduction to lactate</strong> by LDH — anaerobic muscle, red cells, and the</p></li></ol><p>Cori cycle with the liver.</p><ol><li><p><strong>Carboxylation to oxaloacetate</strong> by pyruvate carboxylase — the first</p></li></ol><p>committed step of gluconeogenesis and an anaplerotic refill for the TCA    cycle.</p><ol><li><p><strong>Transamination to alanine</strong> — the glucose-alanine cycle between muscle</p></li></ol><p>and liver.</p><ol><li><p>In yeast, decarboxylation to acetaldehyde and ethanol — fermentation,</p></li></ol><p>tested as general biochemistry rather than human.</p><h2>Regulation: Fed versus Fasting State</h2><p>The three irreversible enzymes let the pathway respond to the body''s fuel state:</p><ul><li><p><strong>Hexokinase vs glucokinase</strong> — hexokinase''s low Km means it works at all</p></li></ul><p>times in all tissues; the liver''s glucokinase, with its high Km and its   induction by insulin, only engages when blood glucose is high after a meal.   This is why the liver buffers blood glucose but does not compete for it   when glucose is scarce.</p><ul><li><p><strong>PFK-1 and fructose-2,6-bisphosphate</strong> — in the fed state, insulin raises</p></li></ul><p>fructose-2,6-bisphosphate (through activation of the kinase domain of the   bifunctional PFK-2/FBPase-2 enzyme) and glycolysis accelerates. In   fasting, glucagon shifts the same bifunctional enzyme to its phosphatase   mode, fructose-2,6-bisphosphate falls, PFK-1 slows, and the liver switches   to gluconeogenesis.</p><ul><li><p><strong>Pyruvate kinase</strong> — the liver isoenzyme is phosphorylated and</p></li></ul><p>inactivated by the glucagon-driven cAMP cascade, reinforcing the   fasting-state shutdown; the muscle and brain isoenzymes are not   glucagon-sensitive and keep glycolysis running for their own needs.</p><p>The unifying idea for the viva: <strong>glycolysis is promoted by insulin and inhibited by glucagon in the liver, but is always allowed to run in the brain and red cells, which cannot burn anything else.</strong></p><h2>Clinical Correlations</h2><ul><li><p><strong>LDH isoenzymes:</strong> LDH is a tetramer of H and M subunits — LDH-1 (H4)</p></li></ul><p>is dominant in heart, LDH-5 (M4) in liver and skeletal muscle. Historically   the LDH-1 greater than LDH-2 "flipped pattern" supported myocardial   infarction; today troponin has replaced it, but the isoenzyme logic still   appears in exams.</p><ul><li><p><strong>Lactic acidosis:</strong> Type A from tissue hypoxia (shock, severe asthma,</p></li></ul><p>seizures); Type B without hypoxia — metformin in renal failure, alcohol,   mitochondrial disorders. Anion-gap metabolic acidosis with elevated lactate.</p><ul><li><p><strong>Pyruvate kinase deficiency:</strong> chronic haemolytic anaemia; red cells</p></li></ul><p>cannot sustain ATP and deformability. Interestingly the blocked distal   pathway shunts intermediates to 2,3-BPG, which raises it and shifts the   oxygen dissociation curve right, easing tissue oxygen delivery.</p><ul><li><p><strong>Cancer metabolism — the Warburg effect:</strong> tumours run glycolysis to</p></li></ul><p>lactate even in oxygen, the principle behind PET imaging with   fluorodeoxyglucose, which is trapped intracellularly once phosphorylated by   hexokinase.</p><h2>Revision Pointers</h2><p>Write the ten enzymes in order before checking the table, then mark the three irreversible steps — those are your regulation questions and the gluconeogenesis bypasses (glucose-6-phosphatase, fructose-1,6-bisphosphatase, PEP carboxykinase plus pyruvate carboxylase). Link the energetics forward to the TCA cycle and backwards to glycogen, and test yourself with the <a href="/practice/quiz/biochemistry/" rel="noopener">biochemistry practice quiz</a>. For how the hypoxic heart pays its energy bill, see the <a href="/notes/cardiac-cycle/" rel="noopener">cardiac cycle study note</a>.</p><h2>Learning objectives</h2><ul><li><p>List the ten reactions of glycolysis in order with their enzymes</p></li><li><p>Distinguish the investment phase from the payoff phase energetically</p></li><li><p>Explain the three irreversible, regulated steps and their allosteric modulators</p></li><li><p>Calculate the net ATP and NADH yield per glucose under aerobic and anaerobic conditions</p></li><li><p>Describe the five fates of pyruvate and their physiological contexts</p></li><li><p>Interpret LDH isoenzymes, lactic acidosis and pyruvate kinase deficiency clinically</p></li></ul><h2>Key terms</h2><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Glycolysis</strong> — The cytosolic pathway that converts one glucose molecule to two pyruvate molecules, the central route of carbohydrate catabolism.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Rate-limiting enzyme</strong> — Phosphofructokinase-1 (PFK-1), the slowest and most tightly controlled enzyme of glycolysis.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Substrate-level phosphorylation</strong> — ATP production by transfer of a phosphate from a high-energy metabolic intermediate directly to ADP, without the electron transport chain.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Fructose-2,6-bisphosphate</strong> — The most potent allosteric activator of PFK-1; its level rises with insulin and falls with glucagon.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Cori cycle</strong> — The lactate shuttle in which muscle anaerobic glycolysis exports lactate to the liver, which reconverts it to glucose.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Lactate dehydrogenase</strong> — The enzyme that reduces pyruvate to lactate while regenerating NAD+ for continued glycolysis under anaerobic conditions.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Warburg effect</strong> — The tendency of rapidly dividing tumour cells to ferment glucose to lactate even when oxygen is available.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Pasteur effect</strong> — The slowing of glycolysis in the presence of oxygen, because oxidative phosphorylation yields far more ATP and suppresses the pathway''s rate.</p></aside><h2>Important points</h2><aside class="msn-block msn-important" data-type="important"><p class="msn-block-label">Important</p><ul><li><p>Glycolysis occurs in the cytosol, needs no oxygen and no mitochondria, and is therefore universal to all cells including mature red cells.</p></li><li><p>Two steps consume ATP (hexokinase/glucokinase and PFK-1) and two produce it (phosphoglycerate kinase and pyruvate kinase) — per glucose the pathway pays 2 and earns 4 ATP.</p></li><li><p>Only three steps are irreversible — hexokinase, PFK-1 and pyruvate kinase — and these are the regulated steps and the gluconeogenesis bypasses.</p></li><li><p>PFK-1 is the rate-limiting enzyme; AMP and fructose-2,6-bisphosphate activate it, ATP and citrate inhibit it.</p></li><li><p>The only oxidation step is glyceraldehyde-3-phosphate dehydrogenase, producing 2 NADH per glucose.</p></li><li><p>Anaerobic net yield is 2 ATP per glucose; aerobic yield from glycolysis proper is about 7 ATP equivalent (2 substrate-level plus 2 NADH).</p></li><li><p>Fluoride inhibits enolase, which is why fluoride tubes are used for blood glucose estimation.</p></li></ul></aside><h2>Key formulas</h2><aside class="msn-block msn-key-point" data-type="key-point"><p class="msn-block-label">Key point</p><p><strong>Glucose + 2 NAD+ + 2 ADP + 2 Pi → 2 Pyruvate + 2 NADH + 2 H+ + 2 ATP + 2 H2O</strong> — The overall balanced equation of glycolysis to pyruvate.</p></aside><aside class="msn-block msn-key-point" data-type="key-point"><p class="msn-block-label">Key point</p><p><strong>Net ATP (anaerobic) = 4 produced − 2 invested = 2 ATP per glucose</strong> — The energy yield when pyruvate is reduced to lactate and NADH is recycled internally.</p></aside><aside class="msn-block msn-key-point" data-type="key-point"><p class="msn-block-label">Key point</p><p><strong>Glucose → 2 Lactate + 2 H+ (net 2 ATP)</strong> — Anaerobic glycolysis overall; the proton production is the biochemical basis of lactic acidosis.</p></aside><h2>Summary</h2><aside class="msn-block msn-key-point" data-type="key-point"><p class="msn-block-label">Key point</p><p>Glycolysis is the cytosolic, oxygen-independent conversion of glucose to two pyruvate molecules through ten enzyme-catalysed steps. The first five steps invest 2 ATP to split and phosphorylate the hexose; the payoff phase yields 4 ATP and 2 NADH per glucose, for a net of 2 ATP anaerobically and about 7 ATP equivalent aerobically. Regulation concentrates on the three irreversible enzymes — hexokinase, PFK-1 and pyruvate kinase — with PFK-1 rate-limiting and responsive to the insulin-glucagon axis through fructose-2,6-bisphosphate. Pyruvate then branches to acetyl-CoA, lactate, oxaloacetate or alanine, and the clinical face of the pathway appears as LDH isoenzymes, lactic acidosis, and pyruvate kinase deficiency.</p></aside><h2>Frequently asked questions</h2><h3>Why is phosphofructokinase-1 called the rate-limiting enzyme of glycolysis?</h3><p>It catalyses the slowest, essentially irreversible step — fructose-6-phosphate to fructose-1,6-bisphosphate — and it integrates the cell''s energy state: AMP and fructose-2,6-bisphosphate speed it up, while ATP and citrate slow it down. Flux through PFK-1 sets the flux through the whole pathway.</p><h3>What is the net ATP yield of glycolysis per glucose?</h3><p>Two ATP anaerobically: four produced by substrate-level phosphorylation minus two invested in the hexokinase and PFK-1 steps. Aerobically the 2 NADH add about 5 more ATP equivalents via shuttles, giving roughly 7 ATP equivalent from glycolysis itself, before the pyruvate enters the TCA cycle.</p><h3>How does glycolysis continue in the absence of oxygen?</h3><p>Lactate dehydrogenase reduces pyruvate to lactate, oxidizing NADH back to NAD+. This regenerates the NAD+ that glyceraldehyde-3-phosphate dehydrogenase needs, so the payoff phase can keep running and the cell keeps its net 2 ATP.</p><h3>Why does pyruvate kinase deficiency cause haemolytic anaemia?</h3><p>Mature red blood cells depend entirely on glycolysis for ATP because they have no mitochondria. When pyruvate kinase fails, ATP falls, the red cell cannot maintain its membrane pumps and shape, and it is destroyed in the spleen — a chronic haemolytic anaemia that usually presents in childhood.</p><aside class="msn-block msn-references" data-type="references"><p class="msn-block-label">References</p><ol><li>Harper''s Illustrated Biochemistry. McGraw Hill</li><li>Lippincott Illustrated Reviews: Biochemistry. Wolters Kluwer</li></ol></aside>',
