INSERT INTO articles (
  title, slug, excerpt, content_json, content_html, article_type, status, subject_id, topic_id, author_id, published_at, seo_title, meta_description, robots, reading_minutes, created_at, updated_at
) VALUES (
  'Incidence vs Prevalence: Complete Study Notes',
  'incidence-vs-prevalence',
  'Epidemiology notes on incidence versus prevalence: definitions, the bathwater analogy, prevalence equals incidence times duration, study designs, and worked numeric examples.',
  '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Overview"}]},{"type":"paragraph","content":[{"type":"text","text":"These notes define incidence and prevalence, connect them through the bathwater analogy and the relationship prevalence approximates incidence times duration, show which study designs measure each, and work through numeric examples — including how prevalence moves predictive values."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Introduction"}]},{"type":"paragraph","content":[{"type":"text","text":"Incidence and prevalence are the two words students most often blur and examiners most often separate. The blur is understandable — both are counts of cases over people — but the distinction decides whether you are measuring risk or measuring burden, and whether your study design is even capable of the measurement you intend. These notes build the distinction from definitions, through the analogy that makes it permanent, to the arithmetic that appears in every paper and viva."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Definitions"}]},{"type":"paragraph","content":[{"type":"text","text":"Incidence","marks":[{"type":"bold"}]},{"type":"text","text":" measures new cases:"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Incidence rate = (number of "},{"type":"text","text":"new","marks":[{"type":"bold"}]},{"type":"text","text":" cases arising during a specified period) ÷ (number of persons "},{"type":"text","text":"at risk","marks":[{"type":"bold"}]},{"type":"text","text":" during that period) × a convenient multiplier (per 1,000 or per 100,000)."}]}]},{"type":"paragraph","content":[{"type":"text","text":"The denominator is the population at risk — existing cases are excluded, because a person who already has the disease cannot become a new case of it. Depending on the data, this is refined into an incidence density (person-time) when follow-up times differ."}]},{"type":"paragraph","content":[{"type":"text","text":"Prevalence","marks":[{"type":"bold"}]},{"type":"text","text":" measures existing cases:"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Point prevalence = (all cases existing at a given moment) ÷ (total population at that moment) × multiplier."}]}]},{"type":"paragraph","content":[{"type":"text","text":"Period prevalence","marks":[{"type":"bold"}]},{"type":"text","text":" counts everyone who had the disease at any time during a defined span — existing at the start plus new during it — divided by the population. Exams usually mean point prevalence unless they say otherwise."}]},{"type":"paragraph","content":[{"type":"text","text":"The critical contrast in one line: "},{"type":"text","text":"incidence is a rate with a time dimension; point prevalence is a proportion, a snapshot.","marks":[{"type":"bold"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Bathwater Analogy"}]},{"type":"paragraph","content":[{"type":"text","text":"Picture a bathtub:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"faucet","marks":[{"type":"bold"}]},{"type":"text","text":" is incidence — new cases flowing in."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"water level","marks":[{"type":"bold"}]},{"type":"text","text":" is prevalence — how much disease is present right now."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"drain","marks":[{"type":"bold"}]},{"type":"text","text":" is recovery and death — cases leaving the pool."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Three consequences follow immediately:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Turn the faucet up (higher incidence) and the level rises."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Block the drain (better treatment that prolongs life without curing, as"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"in AIDS after antiretroviral therapy or many cancers) and the level rises    "},{"type":"text","text":"even as incidence stays flat","marks":[{"type":"bold"}]},{"type":"text","text":" — a public health success that increases    prevalence."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A fast drain (rapid cure or rapid death) keeps the level low even with a"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"strong faucet."}]},{"type":"paragraph","content":[{"type":"text","text":"This is why chronic diseases dominate prevalence tables while acute infections dominate incidence reporting."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Relationship: P ≈ I × D"}]},{"type":"paragraph","content":[{"type":"text","text":"In a steady state, where incidence and duration are roughly constant:"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Prevalence ≈ Incidence × Average duration","marks":[{"type":"bold"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Worked example: an incidence of 2 per 1,000 per year and an average disease duration of 5 years gives a prevalence of about 10 per 1,000 — one percent of the population living with the disease at any moment. Rearranged, the same relation lets you estimate any one of the three from the other two, a favourite one-mark MCQ."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Which Study Design Measures Which?"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Design"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Measures"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Why"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Cross-sectional survey"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Prevalence"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"One time point; cases are counted, not watched for onset"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Cohort study"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Incidence"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Defined population followed forward; new cases observed as they occur"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Randomized controlled trial"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Incidence (in each arm)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Follow-up from intervention to outcome"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Surveillance and registry data"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Incidence and prevalence"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Notifiable disease counts feed both"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Screening programme data"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Prevalence (heavily)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Screening preferentially finds long-duration cases — length-time bias"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The case-control study measures neither directly — it starts from cases and controls and estimates an odds ratio — but it is conceptually anchored to incidence, which is why its results approximate incidence-rate ratios when the disease is rare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Worked Numeric Examples"}]},{"type":"paragraph","content":[{"type":"text","text":"Example 1 — basic calculation.","marks":[{"type":"bold"}]},{"type":"text","text":" A town of 10,000 has 500 people already living with hypertension on 1 January; during the year, 200 more are newly diagnosed."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Point prevalence at 1 January = 500 ÷ 10,000 = "},{"type":"text","text":"5 percent","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Incidence during the year = 200 ÷ (10,000 − 500) = 200 ÷ 9,500 ≈"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"2.1 percent per year","marks":[{"type":"bold"}]},{"type":"text","text":" (21 per 1,000 per year)."}]},{"type":"paragraph","content":[{"type":"text","text":"Note both exam traps: the prevalence denominator is the whole population, and the incidence denominator excludes the existing cases."}]},{"type":"paragraph","content":[{"type":"text","text":"Example 2 — prevalence drives predictive value.","marks":[{"type":"bold"}]},{"type":"text","text":" A screening test with 90 percent sensitivity and 90 percent specificity is applied to two populations of 1,000:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Population A (prevalence 1 percent)"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Population B (prevalence 50 percent)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"True positives"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"9"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"450"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"False positives"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"99"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"50"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"True negatives"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"891"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"450"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"False negatives"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"50"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Positive predictive value","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"9 ÷ 108 ≈ "},{"type":"text","text":"8 percent","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"450 ÷ 500 = "},{"type":"text","text":"90 percent","marks":[{"type":"bold"}]}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Negative predictive value","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"891 ÷ 892 ≈ "},{"type":"text","text":"99.9 percent","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"450 ÷ 500 = "},{"type":"text","text":"90 percent","marks":[{"type":"bold"}]}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The test did not change; the population did. In a low-prevalence setting — screening the general public — most positives are false positives, which is why screening programmes are targeted and confirmatory tests are mandatory. This is the bridge into the "},{"type":"text","text":"diagnostic test accuracy topic hub","marks":[{"type":"link","attrs":{"href":"/topics/diagnostic-test-accuracy/"}}]},{"type":"text","text":", where sensitivity, specificity and predictive values are treated in full."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Exam Framing"}]},{"type":"paragraph","content":[{"type":"text","text":"A viva framing that recurs: "},{"type":"text","text":"your district shows a rising prevalence of diabetes but a stable incidence — interpret.","marks":[{"type":"italic"}]},{"type":"text","text":" The correct reasoning: the flow of new cases has not increased, but cases are accumulating — either better survival, earlier detection, longer duration, or in-migration of cases. Distinguish cause before celebrating or panicking. The mirror-image question — falling prevalence with stable incidence — points to faster cure or faster death. Examiners award marks for the reasoning, not the recall."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Revision Pointers"}]},{"type":"paragraph","content":[{"type":"text","text":"Write the two formulas side by side and annotate the denominators — that is where the marks are lost. Practice the bathtub explanation aloud, because viva examiners reward a clear analogy used precisely. Then work the two numeric examples until the predictive-value flip feels obvious rather than surprising, and drill with the "},{"type":"text","text":"community medicine practice quiz","marks":[{"type":"link","attrs":{"href":"/practice/quiz/community-medicine/"}}]},{"type":"text","text":". For the biostatistics that follows — rates standardization and test statistics — keep the "},{"type":"text","text":"diagnostic test accuracy topic hub","marks":[{"type":"link","attrs":{"href":"/topics/diagnostic-test-accuracy/"}}]},{"type":"text","text":" and these notes together in revision."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Learning objectives"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define incidence and prevalence precisely, including point and period prevalence"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain the relationship prevalence approximates incidence times average duration"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Identify which study designs measure incidence and which measure prevalence"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Calculate incidence and prevalence from population data"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distinguish the uses of each measure in describing disease burden and risk"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain how prevalence changes the predictive value of a diagnostic test"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Key terms"}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Incidence","marks":[{"type":"bold"}]},{"type":"text","text":" — The number of new cases arising in a defined population at risk during a specified time period."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Prevalence","marks":[{"type":"bold"}]},{"type":"text","text":" — The proportion of a population that has the disease at a given point in time (point prevalence) or during a period (period prevalence)."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Population at risk","marks":[{"type":"bold"}]},{"type":"text","text":" — The people who could become cases — those without the disease and not immune; the correct denominator for incidence."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Period prevalence","marks":[{"type":"bold"}]},{"type":"text","text":" — All cases existing at the start of a period plus new cases arising during it, divided by the population."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Duration of disease","marks":[{"type":"bold"}]},{"type":"text","text":" — Average time from onset to recovery or death; with incidence, it sets the prevalence of a chronic disease."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Cross-sectional study","marks":[{"type":"bold"}]},{"type":"text","text":" — A study measuring exposure and disease at one point in time; it estimates prevalence, not incidence."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Cohort study","marks":[{"type":"bold"}]},{"type":"text","text":" — A study following exposed and unexposed people forward in time; it measures incidence directly."}]}]},{"type":"definition","content":[{"type":"paragraph","content":[{"type":"text","text":"Positive predictive value","marks":[{"type":"bold"}]},{"type":"text","text":" — The proportion of people testing positive who truly have the disease — it rises and falls with prevalence."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Important points"}]},{"type":"important","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Incidence counts new cases; prevalence counts all existing cases."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Incidence measures risk and causes; prevalence measures burden and chronic disease load."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prevalence approximates incidence multiplied by average duration in a steady state."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Diseases of long duration accumulate high prevalence even at low incidence; diseases of short duration or high fatality stay low."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cross-sectional surveys and screening data measure prevalence; cohort studies, trials and surveillance measure incidence."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The incidence denominator excludes existing cases; the prevalence denominator is the total population."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Positive predictive value rises with prevalence even when sensitivity and specificity stay constant — the base-rate effect."}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Key formulas"}]},{"type":"keyPoint","content":[{"type":"paragraph","content":[{"type":"text","text":"Incidence rate = (New cases during period ÷ Population at risk) × multiplier","marks":[{"type":"bold"}]},{"type":"text","text":" — New cases per population at risk over a defined period, reported per 1,000 or 100,000 as appropriate."}]}]},{"type":"keyPoint","content":[{"type":"paragraph","content":[{"type":"text","text":"Point prevalence = (All existing cases at a point in time ÷ Total population) × multiplier","marks":[{"type":"bold"}]},{"type":"text","text":" — The snapshot proportion of the population currently with the disease."}]}]},{"type":"keyPoint","content":[{"type":"paragraph","content":[{"type":"text","text":"Prevalence ≈ Incidence × Average duration","marks":[{"type":"bold"}]},{"type":"text","text":" — For a stable chronic disease, prevalence is the product of how fast cases arrive and how long they stay."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Summary"}]},{"type":"keyPoint","content":[{"type":"paragraph","content":[{"type":"text","text":"Incidence is the flow of new cases into a population at risk over a period; prevalence is the stock of existing cases at a point in time. The bathwater analogy captures the relationship — incidence is water entering the tub, prevalence is the water level, and recovery and death are the drain — formalized as prevalence approximating incidence times average duration. Cross-sectional studies and screening measure prevalence, cohort studies and clinical trials measure incidence, and the choice matters because prevalence answers how common a disease is while incidence answers what the risk of getting it is. Finally, prevalence directly shapes test interpretation: at low prevalence even an excellent test yields a low positive predictive value, the single most tested idea connecting epidemiology to the diagnostic-test-accuracy question."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Frequently asked questions"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Why can prevalence never exceed incidence in a very short-lasting disease?"}]},{"type":"paragraph","content":[{"type":"text","text":"In diseases that resolve or kill quickly — the common cold, most acute infections — cases leave the pool as fast as they enter, so the snapshot count stays low no matter how fast new cases arrive. High prevalence needs duration: type 2 diabetes has modest incidence but lifelong duration, so its prevalence is enormous."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Which is the better measure for planning health services, incidence or prevalence?"}]},{"type":"paragraph","content":[{"type":"text","text":"Prevalence, because services must care for everyone who currently has the disease, not only the newly diagnosed. Incidence is the better measure for identifying causes and for vaccine or prevention programmes, because only new cases can reveal the effect of exposures on risk."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"In a stable population of 10,000 with 500 existing cases and 200 new cases in a year, what are the prevalence and incidence?"}]},{"type":"paragraph","content":[{"type":"text","text":"Point prevalence at the start of the year = 500 ÷ 10,000 = 5 percent. The incidence during the year = 200 ÷ (10,000 − 500) = 200 ÷ 9,500 ≈ 2.1 percent per year, because the 500 existing cases are not at risk and must be removed from the denominator."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"If a test has 90 percent sensitivity and 90 percent specificity, why does its positive predictive value change between populations?"}]},{"type":"paragraph","content":[{"type":"text","text":"Predictive values depend on how many truly diseased people are in the tested group. At 1 percent prevalence, 1,000 people yield 9 true positives against 99 false positives — a positive predictive value of only about 8 percent. At 50 percent prevalence the same test yields 450 true positives against 50 false positives — 90 percent. The test is unchanged; the base rate moved the answer."}]},{"type":"references","attrs":{"items":[{"title":"Park''s Textbook of Preventive and Social Medicine","source":"Banarsidas Bhanot"},{"title":"Gordis Epidemiology","source":"Elsevier"},{"title":"Bonita, Beaglehole, Kjellstrom: Basic Epidemiology","source":"World Health Organization"}]}}]}',
  '<h2>Overview</h2><p>These notes define incidence and prevalence, connect them through the bathwater analogy and the relationship prevalence approximates incidence times duration, show which study designs measure each, and work through numeric examples — including how prevalence moves predictive values.</p><h2>Introduction</h2><p>Incidence and prevalence are the two words students most often blur and examiners most often separate. The blur is understandable — both are counts of cases over people — but the distinction decides whether you are measuring risk or measuring burden, and whether your study design is even capable of the measurement you intend. These notes build the distinction from definitions, through the analogy that makes it permanent, to the arithmetic that appears in every paper and viva.</p><h2>Definitions</h2><p><strong>Incidence</strong> measures new cases:</p><blockquote><p>Incidence rate = (number of <strong>new</strong> cases arising during a specified period) ÷ (number of persons <strong>at risk</strong> during that period) × a convenient multiplier (per 1,000 or per 100,000).</p></blockquote><p>The denominator is the population at risk — existing cases are excluded, because a person who already has the disease cannot become a new case of it. Depending on the data, this is refined into an incidence density (person-time) when follow-up times differ.</p><p><strong>Prevalence</strong> measures existing cases:</p><blockquote><p>Point prevalence = (all cases existing at a given moment) ÷ (total population at that moment) × multiplier.</p></blockquote><p><strong>Period prevalence</strong> counts everyone who had the disease at any time during a defined span — existing at the start plus new during it — divided by the population. Exams usually mean point prevalence unless they say otherwise.</p><p>The critical contrast in one line: <strong>incidence is a rate with a time dimension; point prevalence is a proportion, a snapshot.</strong></p><h2>The Bathwater Analogy</h2><p>Picture a bathtub:</p><ul><li><p>The <strong>faucet</strong> is incidence — new cases flowing in.</p></li><li><p>The <strong>water level</strong> is prevalence — how much disease is present right now.</p></li><li><p>The <strong>drain</strong> is recovery and death — cases leaving the pool.</p></li></ul><p>Three consequences follow immediately:</p><ol><li><p>Turn the faucet up (higher incidence) and the level rises.</p></li><li><p>Block the drain (better treatment that prolongs life without curing, as</p></li></ol><p>in AIDS after antiretroviral therapy or many cancers) and the level rises    <strong>even as incidence stays flat</strong> — a public health success that increases    prevalence.</p><ol><li><p>A fast drain (rapid cure or rapid death) keeps the level low even with a</p></li></ol><p>strong faucet.</p><p>This is why chronic diseases dominate prevalence tables while acute infections dominate incidence reporting.</p><h2>The Relationship: P ≈ I × D</h2><p>In a steady state, where incidence and duration are roughly constant:</p><blockquote><p><strong>Prevalence ≈ Incidence × Average duration</strong></p></blockquote><p>Worked example: an incidence of 2 per 1,000 per year and an average disease duration of 5 years gives a prevalence of about 10 per 1,000 — one percent of the population living with the disease at any moment. Rearranged, the same relation lets you estimate any one of the three from the other two, a favourite one-mark MCQ.</p><h2>Which Study Design Measures Which?</h2><table><tbody><tr><th><p>Design</p></th><th><p>Measures</p></th><th><p>Why</p></th></tr><tr><td><p>Cross-sectional survey</p></td><td><p>Prevalence</p></td><td><p>One time point; cases are counted, not watched for onset</p></td></tr><tr><td><p>Cohort study</p></td><td><p>Incidence</p></td><td><p>Defined population followed forward; new cases observed as they occur</p></td></tr><tr><td><p>Randomized controlled trial</p></td><td><p>Incidence (in each arm)</p></td><td><p>Follow-up from intervention to outcome</p></td></tr><tr><td><p>Surveillance and registry data</p></td><td><p>Incidence and prevalence</p></td><td><p>Notifiable disease counts feed both</p></td></tr><tr><td><p>Screening programme data</p></td><td><p>Prevalence (heavily)</p></td><td><p>Screening preferentially finds long-duration cases — length-time bias</p></td></tr></tbody></table><p>The case-control study measures neither directly — it starts from cases and controls and estimates an odds ratio — but it is conceptually anchored to incidence, which is why its results approximate incidence-rate ratios when the disease is rare.</p><h2>Worked Numeric Examples</h2><p><strong>Example 1 — basic calculation.</strong> A town of 10,000 has 500 people already living with hypertension on 1 January; during the year, 200 more are newly diagnosed.</p><ul><li><p>Point prevalence at 1 January = 500 ÷ 10,000 = <strong>5 percent</strong>.</p></li><li><p>Incidence during the year = 200 ÷ (10,000 − 500) = 200 ÷ 9,500 ≈</p></li></ul><p><strong>2.1 percent per year</strong> (21 per 1,000 per year).</p><p>Note both exam traps: the prevalence denominator is the whole population, and the incidence denominator excludes the existing cases.</p><p><strong>Example 2 — prevalence drives predictive value.</strong> A screening test with 90 percent sensitivity and 90 percent specificity is applied to two populations of 1,000:</p><table><tbody><tr><th><p></p></th><th><p>Population A (prevalence 1 percent)</p></th><th><p>Population B (prevalence 50 percent)</p></th></tr><tr><td><p>True positives</p></td><td><p>9</p></td><td><p>450</p></td></tr><tr><td><p>False positives</p></td><td><p>99</p></td><td><p>50</p></td></tr><tr><td><p>True negatives</p></td><td><p>891</p></td><td><p>450</p></td></tr><tr><td><p>False negatives</p></td><td><p>1</p></td><td><p>50</p></td></tr><tr><td><p><strong>Positive predictive value</strong></p></td><td><p>9 ÷ 108 ≈ <strong>8 percent</strong></p></td><td><p>450 ÷ 500 = <strong>90 percent</strong></p></td></tr><tr><td><p><strong>Negative predictive value</strong></p></td><td><p>891 ÷ 892 ≈ <strong>99.9 percent</strong></p></td><td><p>450 ÷ 500 = <strong>90 percent</strong></p></td></tr></tbody></table><p>The test did not change; the population did. In a low-prevalence setting — screening the general public — most positives are false positives, which is why screening programmes are targeted and confirmatory tests are mandatory. This is the bridge into the <a href="/topics/diagnostic-test-accuracy/" rel="noopener">diagnostic test accuracy topic hub</a>, where sensitivity, specificity and predictive values are treated in full.</p><h2>Exam Framing</h2><p>A viva framing that recurs: <em>your district shows a rising prevalence of diabetes but a stable incidence — interpret.</em> The correct reasoning: the flow of new cases has not increased, but cases are accumulating — either better survival, earlier detection, longer duration, or in-migration of cases. Distinguish cause before celebrating or panicking. The mirror-image question — falling prevalence with stable incidence — points to faster cure or faster death. Examiners award marks for the reasoning, not the recall.</p><h2>Revision Pointers</h2><p>Write the two formulas side by side and annotate the denominators — that is where the marks are lost. Practice the bathtub explanation aloud, because viva examiners reward a clear analogy used precisely. Then work the two numeric examples until the predictive-value flip feels obvious rather than surprising, and drill with the <a href="/practice/quiz/community-medicine/" rel="noopener">community medicine practice quiz</a>. For the biostatistics that follows — rates standardization and test statistics — keep the <a href="/topics/diagnostic-test-accuracy/" rel="noopener">diagnostic test accuracy topic hub</a> and these notes together in revision.</p><h2>Learning objectives</h2><ul><li><p>Define incidence and prevalence precisely, including point and period prevalence</p></li><li><p>Explain the relationship prevalence approximates incidence times average duration</p></li><li><p>Identify which study designs measure incidence and which measure prevalence</p></li><li><p>Calculate incidence and prevalence from population data</p></li><li><p>Distinguish the uses of each measure in describing disease burden and risk</p></li><li><p>Explain how prevalence changes the predictive value of a diagnostic test</p></li></ul><h2>Key terms</h2><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Incidence</strong> — The number of new cases arising in a defined population at risk during a specified time period.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Prevalence</strong> — The proportion of a population that has the disease at a given point in time (point prevalence) or during a period (period prevalence).</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Population at risk</strong> — The people who could become cases — those without the disease and not immune; the correct denominator for incidence.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Period prevalence</strong> — All cases existing at the start of a period plus new cases arising during it, divided by the population.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Duration of disease</strong> — Average time from onset to recovery or death; with incidence, it sets the prevalence of a chronic disease.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Cross-sectional study</strong> — A study measuring exposure and disease at one point in time; it estimates prevalence, not incidence.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Cohort study</strong> — A study following exposed and unexposed people forward in time; it measures incidence directly.</p></aside><aside class="msn-block msn-definition" data-type="definition"><p class="msn-block-label">Definition</p><p><strong>Positive predictive value</strong> — The proportion of people testing positive who truly have the disease — it rises and falls with prevalence.</p></aside><h2>Important points</h2><aside class="msn-block msn-important" data-type="important"><p class="msn-block-label">Important</p><ul><li><p>Incidence counts new cases; prevalence counts all existing cases.</p></li><li><p>Incidence measures risk and causes; prevalence measures burden and chronic disease load.</p></li><li><p>Prevalence approximates incidence multiplied by average duration in a steady state.</p></li><li><p>Diseases of long duration accumulate high prevalence even at low incidence; diseases of short duration or high fatality stay low.</p></li><li><p>Cross-sectional surveys and screening data measure prevalence; cohort studies, trials and surveillance measure incidence.</p></li><li><p>The incidence denominator excludes existing cases; the prevalence denominator is the total population.</p></li><li><p>Positive predictive value rises with prevalence even when sensitivity and specificity stay constant — the base-rate effect.</p></li></ul></aside><h2>Key formulas</h2><aside class="msn-block msn-key-point" data-type="key-point"><p class="msn-block-label">Key point</p><p><strong>Incidence rate = (New cases during period ÷ Population at risk) × multiplier</strong> — New cases per population at risk over a defined period, reported per 1,000 or 100,000 as appropriate.</p></aside><aside class="msn-block msn-key-point" data-type="key-point"><p class="msn-block-label">Key point</p><p><strong>Point prevalence = (All existing cases at a point in time ÷ Total population) × multiplier</strong> — The snapshot proportion of the population currently with the disease.</p></aside><aside class="msn-block msn-key-point" data-type="key-point"><p class="msn-block-label">Key point</p><p><strong>Prevalence ≈ Incidence × Average duration</strong> — For a stable chronic disease, prevalence is the product of how fast cases arrive and how long they stay.</p></aside><h2>Summary</h2><aside class="msn-block msn-key-point" data-type="key-point"><p class="msn-block-label">Key point</p><p>Incidence is the flow of new cases into a population at risk over a period; prevalence is the stock of existing cases at a point in time. The bathwater analogy captures the relationship — incidence is water entering the tub, prevalence is the water level, and recovery and death are the drain — formalized as prevalence approximating incidence times average duration. Cross-sectional studies and screening measure prevalence, cohort studies and clinical trials measure incidence, and the choice matters because prevalence answers how common a disease is while incidence answers what the risk of getting it is. Finally, prevalence directly shapes test interpretation: at low prevalence even an excellent test yields a low positive predictive value, the single most tested idea connecting epidemiology to the diagnostic-test-accuracy question.</p></aside><h2>Frequently asked questions</h2><h3>Why can prevalence never exceed incidence in a very short-lasting disease?</h3><p>In diseases that resolve or kill quickly — the common cold, most acute infections — cases leave the pool as fast as they enter, so the snapshot count stays low no matter how fast new cases arrive. High prevalence needs duration: type 2 diabetes has modest incidence but lifelong duration, so its prevalence is enormous.</p><h3>Which is the better measure for planning health services, incidence or prevalence?</h3><p>Prevalence, because services must care for everyone who currently has the disease, not only the newly diagnosed. Incidence is the better measure for identifying causes and for vaccine or prevention programmes, because only new cases can reveal the effect of exposures on risk.</p><h3>In a stable population of 10,000 with 500 existing cases and 200 new cases in a year, what are the prevalence and incidence?</h3><p>Point prevalence at the start of the year = 500 ÷ 10,000 = 5 percent. The incidence during the year = 200 ÷ (10,000 − 500) = 200 ÷ 9,500 ≈ 2.1 percent per year, because the 500 existing cases are not at risk and must be removed from the denominator.</p><h3>If a test has 90 percent sensitivity and 90 percent specificity, why does its positive predictive value change between populations?</h3><p>Predictive values depend on how many truly diseased people are in the tested group. At 1 percent prevalence, 1,000 people yield 9 true positives against 99 false positives — a positive predictive value of only about 8 percent. At 50 percent prevalence the same test yields 450 true positives against 50 false positives — 90 percent. The test is unchanged; the base rate moved the answer.</p><aside class="msn-block msn-references" data-type="references"><p class="msn-block-label">References</p><ol><li>Park''s Textbook of Preventive and Social Medicine. Banarsidas Bhanot</li><li>Gordis Epidemiology. Elsevier</li><li>Bonita, Beaglehole, Kjellstrom: Basic Epidemiology. World Health Organization</li></ol></aside>',
