INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'By what mechanism does gentamicin kill susceptible aerobic gram-negative bacteria?', 'aminoglycoside-mcq', 'second-professional-mbbs', 'Aminoglycosides bind the 30S subunit, distort the decoding site and impair proofreading, so aberrant proteins are inserted into the cell membrane — the defective membrane itself contributes to the lethal effect, making these drugs bactericidal. The key distractor, 50S binding, is the mechanism of chloramphenicol, clindamycin and the macrolides, while DNA gyrase inhibition belongs to the fluoroquinolones and cell-wall cross-linking to the beta-lactams.', 'published',
  (SELECT id FROM subjects WHERE slug = 'pharmacology'), (SELECT t.id FROM topics t WHERE t.slug = 'antimicrobials' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'pharmacology')), 'medium', '["antimicrobial-resistance"]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
