INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'Which feature best distinguishes apoptosis from necrosis?', 'apoptosis-vs-necrosis-mcq', 'second-professional-mbbs', 'Apoptosis is programmed, gene-directed cell suicide that requires ATP: the cell shrinks, the chromatin condenses and marginates, the membrane blebs, and fragments are phagocytosed without spilling contents, so no inflammatory response follows. The key distractor, swelling and rupture with enzyme release, is the exact description of necrosis, which is a passive consequence of ATP depletion and membrane damage and is accompanied by acute inflammation.', 'published',
  (SELECT id FROM subjects WHERE slug = 'pathology'), (SELECT t.id FROM topics t WHERE t.slug = 'cell-injury' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'pathology')), 'easy', '["inflammation-and-repair"]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'A', 'It is an active, energy-dependent process that typically provokes little or no inflammation', 1, 0 FROM mcqs WHERE slug = 'apoptosis-vs-necrosis-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'It always follows severe ischaemia or membrane injury by toxins', 0, 1 FROM mcqs WHERE slug = 'apoptosis-vs-necrosis-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'It causes cells to swell and rupture, releasing enzymes into surrounding tissue', 0, 2 FROM mcqs WHERE slug = 'apoptosis-vs-necrosis-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', 'It affects large contiguous groups of cells simultaneously', 0, 3 FROM mcqs WHERE slug = 'apoptosis-vs-necrosis-mcq';
