INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'Propranolol lowers blood pressure in a patient with hypertension mainly through which mechanism?', 'beta-blocker-mcq', 'second-professional-mbbs', 'Propranolol is a non-selective beta blocker; its antihypertensive effect comes from three beta-1 consequences — lower heart rate, lower contractility (so lower cardiac output) and reduced renin secretion from juxtaglomerular cells, which together lower both output and angiotensin II-mediated tone. The key distractor, alpha-1 blockade, is the mechanism of prazosin, while calcium channel blockade belongs to amlodipine; the beta-2 option is not a beta blocker action at all.', 'published',
  (SELECT id FROM subjects WHERE slug = 'pharmacology'), (SELECT t.id FROM topics t WHERE t.slug = 'cardiovascular-drugs' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'pharmacology')), 'easy', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
