INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'A newborn delivered after severe shoulder dystocia holds the affected arm adducted and internally rotated against the trunk, with the forearm pronated and the wrist flexed — the classic "waiter''s tip" posture. Which part of the brachial plexus is injured?', 'brachial-plexus-injury-mcq', 'first-professional-mbbs', 'Erb''s palsy injures the C5 and C6 roots forming the upper trunk, the classic birth injury of shoulder dystocia. Loss of the shoulder abductors and lateral rotators (suprascapular and axillary nerves) plus the forearm flexors and supinators (musculocutaneous nerve) produces the adducted, internally rotated, pronated "waiter''s tip" posture, with an absent biceps jerk. The key distractor, C8 and T1, describes Klumpke''s palsy, which instead produces a claw hand from loss of intrinsic hand muscles and may add Horner syndrome.', 'published',
  (SELECT id FROM subjects WHERE slug = 'anatomy'), (SELECT t.id FROM topics t WHERE t.slug = 'upper-limb' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'anatomy')), 'easy', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'A', 'The C5 and C6 nerve roots (upper trunk), damaged by excessive downward traction on the shoulder', 1, 0 FROM mcqs WHERE slug = 'brachial-plexus-injury-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'The C8 and T1 nerve roots (lower trunk), damaged by forced upward abduction of the arm', 0, 1 FROM mcqs WHERE slug = 'brachial-plexus-injury-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'The C7 nerve root alone, damaged by a fall on the outstretched hand', 0, 2 FROM mcqs WHERE slug = 'brachial-plexus-injury-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', 'The posterior cord, compressed against the humerus in the axilla', 0, 3 FROM mcqs WHERE slug = 'brachial-plexus-injury-mcq';
