INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'A resting healthy adult has a stroke volume of 70 mL and a heart rate of 72 beats per minute. What is this person''s cardiac output?', 'cardiac-output-mcq', 'first-professional-mbbs', 'Cardiac output is the product of stroke volume and heart rate, so 0.07 L × 72 beats/min gives about 5.0 L/min, the normal resting value that also matches the volume of the circulating blood turned over once each minute. A distractor of about 10 litres usually comes from doubling the stroke volume or forgetting that the two ventricles eject in series, not in parallel; 0.5 litres is roughly one stroke volume per second and reflects mixing up per-minute and per-beat quantities.', 'published',
  (SELECT id FROM subjects WHERE slug = 'physiology'), (SELECT t.id FROM topics t WHERE t.slug = 'cardiovascular' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'physiology')), 'easy', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
