INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'Which type of necrosis is characteristically associated with Mycobacterium tuberculosis infection?', 'caseous-necrosis-mcq', 'second-professional-mbbs', 'Caseous necrosis is enclosed within a granuloma and looks grossly soft, white and friable, like dry cheese; microscopically the tissue pattern is completely obliterated into amorphous granular debris, and it is virtually diagnostic of tuberculosis. The key distractor, fibrinoid necrosis, is also amorphous and eosinophilic, but it affects blood vessel walls in immune-mediated injury such as malignant hypertension or polyarteritis nodosa, not lobes of tissue framed by epithelioid macrophages.', 'published',
  (SELECT id FROM subjects WHERE slug = 'pathology'), (SELECT t.id FROM topics t WHERE t.slug = 'cell-injury' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'pathology')), 'medium', '["inflammation-and-repair"]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
