INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'Which cranial nerve is the only one that emerges from the dorsal (posterior) aspect of the brainstem?', 'cranial-nerves-mcq', 'first-professional-mbbs', 'The trochlear nerve is uniquely dorsal: it leaves the brainstem below the inferior colliculus, wraps around the midbrain, and crosses completely before exiting, so it is also the only cranial nerve to decussate and the only one to supply the contralateral superior oblique from its nucleus. The key distractor, CN VI, looks tempting because it shares the eye-movement group, but it emerges ventrally at the pontomedullary junction, as CN III does between the cerebral peduncles.', 'published',
  (SELECT id FROM subjects WHERE slug = 'anatomy'), (SELECT t.id FROM topics t WHERE t.slug = 'head-and-neck' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'anatomy')), 'hard', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
