INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'The trochlear nerve (CN IV), emerging just caudal to the inferior colliculus', 1, 1 FROM mcqs WHERE slug = 'cranial-nerves-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'The trigeminal nerve (CN V), emerging from the lateral pons at the middle cerebellar peduncle', 0, 2 FROM mcqs WHERE slug = 'cranial-nerves-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', 'The abducens nerve (CN VI), emerging at the junction of the pons and medulla', 0, 3 FROM mcqs WHERE slug = 'cranial-nerves-mcq';
