INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'At autopsy, which single finding is most indicative that death was due to drowning?', 'drowning-mcq', 'third-professional-mbbs', 'The froth is a mixture of water, mucus, surfactant and protein-rich oedema fluid churned into foam by the victim''s struggling respirations; it is copious, fine and increases on pressure, and it indicates that the person was breathing while submerged. The key distractor, water in the stomach, is unreliable — it may be swallowed agonal fluid, water swallowed before immersion, or contaminant entering after death.', 'published',
  (SELECT id FROM subjects WHERE slug = 'forensic-medicine'), (SELECT t.id FROM topics t WHERE t.slug = 'asphyxia' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'forensic-medicine')), 'hard', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
