INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'In Michaelis–Menten kinetics, the Michaelis constant (Km) is best defined as which of the following?', 'enzyme-kinetics-km-mcq', 'first-professional-mbbs', 'Km has the units of concentration, not velocity, and equals the substrate level that drives the enzyme at half its maximal rate; it is inversely related to apparent substrate affinity, so a low Km means high affinity. The key distractor, the velocity at half of Vmax, is a number in velocity units and cannot be a dissociation-like constant at all, while the turnover description defines kcat, not Km.', 'published',
  (SELECT id FROM subjects WHERE slug = 'biochemistry'), (SELECT t.id FROM topics t WHERE t.slug = 'enzymes' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'biochemistry')), 'medium', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
