INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'Within the femoral triangle, the major structures passing beneath the inguinal ligament are arranged, from lateral to medial, in which order?', 'femoral-triangle-contents-mcq', 'first-professional-mbbs', 'The sequence from lateral to medial is nerve, artery, vein, canal — remembered as NAVY or NAVC. The femoral nerve lies most laterally on iliacus, outside the femoral sheath; the artery and vein share the sheath, with the vein medial to the artery; and the femoral canal is the most medial compartment, containing fat and lymphatics. The key distractor reverses nerve and vessel positions, which would place the nerve inside the sheath next to the canal — anatomically impossible because the nerve never enters the femoral sheath.', 'published',
  (SELECT id FROM subjects WHERE slug = 'anatomy'), (SELECT t.id FROM topics t WHERE t.slug = 'abdomen' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'anatomy')), 'medium', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
