INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'How many net ATP are produced when one molecule of glucose is converted to two molecules of lactate through anaerobic glycolysis?', 'glycolysis-atp-mcq', 'first-professional-mbbs', 'Glycolysis generates 4 ATP by substrate-level phosphorylation — two at the phosphoglycerate kinase step and two at the pyruvate kinase step — but 2 ATP were already spent at hexokinase and phosphofructokinase-1, leaving a net gain of 2 ATP per glucose. The key distractor, 4 ATP, is the gross production, which forgets the investment phase; roughly 30–32 ATP belongs to complete aerobic oxidation, not to the anaerobic pathway alone.', 'published',
  (SELECT id FROM subjects WHERE slug = 'biochemistry'), (SELECT t.id FROM topics t WHERE t.slug = 'carbohydrate-metabolism' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'biochemistry')), 'easy', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
