INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'Why do gram-positive bacteria appear purple after Gram staining while gram-negative bacteria appear pink?', 'gram-stain-mcq', 'second-professional-mbbs', 'The crystal violet–iodine complex is large; during alcohol-acetone decolorization the thick, multi-layer peptidoglycan with its teichoic-acid crosslinks of gram-positive cells dehydrates and traps the complex, so the cells stay purple. In gram-negatives the thin peptidoglycan dissolves out of the dye and the outer membrane is damaged by the decolorizer, letting the complex escape so the colourless cells then stain pink with safranin. The key distractor reverses the counterstain logic — safranin is the pink dye that gram-positives never get to show.', 'published',
  (SELECT id FROM subjects WHERE slug = 'microbiology'), (SELECT t.id FROM topics t WHERE t.slug = 'general-bacteriology' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'microbiology')), 'easy', '["antimicrobial-resistance"]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
