INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'Gram-positive cells take up safranin more avidly than they take up crystal violet', 0, 1 FROM mcqs WHERE slug = 'gram-stain-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'The outer membrane of gram-negative cells traps the crystal violet–iodine complex permanently', 0, 2 FROM mcqs WHERE slug = 'gram-stain-mcq';
