INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'Langhans-type multinucleated giant cells differ from foreign-body-type giant cells in the arrangement of their nuclei. How are the nuclei arranged in a Langhans giant cell?', 'granuloma-mcq', 'second-professional-mbbs', 'Langhans giant cells, formed by fusion of epithelioid macrophages, place their nuclei in a peripheral horseshoe or ring, and are classically seen in tuberculosis and sarcoidosis. The key distractor, randomly scattered nuclei, describes foreign-body giant cells, which form around indigestible material such as sutures or silica. Both are macrophage fusion products; only the nuclear arrangement separates them on routine stains.', 'published',
  (SELECT id FROM subjects WHERE slug = 'pathology'), (SELECT t.id FROM topics t WHERE t.slug = 'cell-injury' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'pathology')), 'hard', '["inflammation-and-repair"]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
