INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'Measles has a basic reproduction number (R0) of roughly 12 to 18. Approximately what proportion of a population must be immune to interrupt sustained measles transmission?', 'herd-immunity-mcq', 'third-professional-mbbs', 'The herd-immunity threshold is 1 − 1/R0; with R0 of 12 to 18 this gives 1 − 1/12 = 0.917 up to 1 − 1/18 = 0.944, so roughly 92–95% of people must be immune. The key distractor of 60–70% is the threshold for a far less transmissible agent (R0 near 3), and 100% is wrong because the very concept of herd immunity is that immune bystanders break the chain of transmission and protect the susceptible remainder.', 'published',
  (SELECT id FROM subjects WHERE slug = 'community-medicine'), (SELECT t.id FROM topics t WHERE t.slug = 'communicable-diseases' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'community-medicine')), 'hard', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'A', 'About 92–95%, derived from the herd-immunity threshold 1 − 1/R0', 1, 0 FROM mcqs WHERE slug = 'herd-immunity-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'About 60–70%, the threshold needed for infections with an R0 near 3', 0, 1 FROM mcqs WHERE slug = 'herd-immunity-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'About 75%, because R0 falls once half the population is vaccinated', 0, 2 FROM mcqs WHERE slug = 'herd-immunity-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', '100%, because a single susceptible person allows an outbreak', 0, 3 FROM mcqs WHERE slug = 'herd-immunity-mcq';
