INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'By what mechanism does HIV enter its principal target cell, the CD4+ helper T lymphocyte?', 'hiv-virus-mcq', 'second-professional-mbbs', 'gp120 first attaches to CD4; this uncovers a second binding site that must engage the chemokine co-receptor, and the conformational change then springs gp41, whose fusion peptide pulls the viral and cellular membranes together. The co-receptor defines tropism — CCR5 on macrophages and memory T cells in transmission, CXCR4 on activated T cells later in disease. The key distractor, CD8 binding, names the wrong receptor entirely, and co-receptor use is precisely why people homozygous for the CCR5-delta32 deletion resist infection.', 'published',
  (SELECT id FROM subjects WHERE slug = 'microbiology'), (SELECT t.id FROM topics t WHERE t.slug = 'virology' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'microbiology')), 'hard', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
