INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'A district health office counts every patient newly diagnosed with pulmonary tuberculosis during 2025 and divides that number by the mid-year population at risk. Which measure has been calculated?', 'incidence-prevalence-mcq', 'third-professional-mbbs', 'Incidence measures new cases arising in a population at risk over a defined period — exactly what the count of 2025 diagnoses divided by the mid-year population gives. The key distractor, prevalence, would include everyone already living with the disease at the start as well as the new cases, since prevalence is a snapshot of all existing cases. Case fatality divides deaths by cases, and attack rate is a short-incidence measure restricted to an exposed epidemic population, such as guests at a wedding.', 'published',
  (SELECT id FROM subjects WHERE slug = 'community-medicine'), (SELECT t.id FROM topics t WHERE t.slug = 'epidemiology' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'community-medicine')), 'easy', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
