INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'In a typical case of suicidal hanging, how does the ligature mark characteristically appear on the neck?', 'ligature-hanging-mcq', 'third-professional-mbbs', 'In hanging the weight of the body pulls the noose upward toward the point of suspension, so the mark is high, oblique and inverted-V shaped, deepest opposite the knot and interrupted where the noose crosses itself or the jaw lifts it off the skin. The key distractor, a horizontal mark at or below the thyroid cartilage, is the classic ligature mark of strangulation by the hands of another, where compressive force is horizontal and usually accompanied by bruising and struggling signs because the victim resists.', 'published',
  (SELECT id FROM subjects WHERE slug = 'forensic-medicine'), (SELECT t.id FROM topics t WHERE t.slug = 'asphyxia' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'forensic-medicine')), 'medium', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
