INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'Pralidoxime can reactivate acetylcholinesterase after organophosphate poisoning, but only if it is given before "aging" occurs. What is aging?', 'organophosphate-mcq', 'second-professional-mbbs', 'The organophosphate first binds the active-site serine reversibly; pralidoxime can still nucleophilically attack and pull the phosphate off at this stage. With time, one alkyl group spontaneously cleaves from the bound phosphate — aging — leaving a strongly negatively charged phosphyl-enzyme that repels the similarly charged pralidoxime, making the inhibition permanent. The key distractor blames hepatic metabolism of pralidoxime, but aging is a change in the enzyme, not in the antidote.', 'published',
  (SELECT id FROM subjects WHERE slug = 'pharmacology'), (SELECT t.id FROM topics t WHERE t.slug = 'autonomic' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'pharmacology')), 'hard', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'A', 'Loss of an alkyl group from the phosphorylated enzyme, which leaves a negatively charged residue that pralidoxime cannot displace', 1, 0 FROM mcqs WHERE slug = 'organophosphate-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'Hepatic metabolism of pralidoxime into an inactive glucuronide conjugate', 0, 1 FROM mcqs WHERE slug = 'organophosphate-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'Internalisation and lysosomal degradation of the inhibited enzyme molecule', 0, 2 FROM mcqs WHERE slug = 'organophosphate-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', 'Regeneration of fresh acetylcholinesterase by the liver, which removes the need for reactivation', 0, 3 FROM mcqs WHERE slug = 'organophosphate-mcq';
