INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'What is the mechanism of the antibacterial action of penicillin?', 'penicillin-mechanism-mcq', 'second-professional-mbbs', 'The beta-lactam ring is a structural mimic of the terminal D-alanine– D-alanine of the pentapeptide side chain; transpeptidases accept it, are acylated, and can no longer form the peptide bridges that give the wall its tensile strength. The weakened wall ruptures under internal osmotic pressure, so penicillin is bactericidal — but only in actively growing cells, since inert bacteria are not building walls. The key distractor, 30S binding, is the aminoglycoside mechanism, not the beta-lactam one.', 'published',
  (SELECT id FROM subjects WHERE slug = 'microbiology'), (SELECT t.id FROM topics t WHERE t.slug = 'general-bacteriology' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'microbiology')), 'medium', '["antimicrobial-resistance"]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'A', 'Inhibition of the transpeptidase enzymes (penicillin-binding proteins) that cross-link peptidoglycan strands', 1, 0 FROM mcqs WHERE slug = 'penicillin-mechanism-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'Irreversible binding to the 30S ribosomal subunit with misreading of mRNA', 0, 1 FROM mcqs WHERE slug = 'penicillin-mechanism-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'Disruption of the cytoplasmic membrane by detergent-like action on phospholipids', 0, 2 FROM mcqs WHERE slug = 'penicillin-mechanism-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', 'Chelation of magnesium ions required for bacterial DNA replication', 0, 3 FROM mcqs WHERE slug = 'penicillin-mechanism-mcq';
