INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'After death, in which muscles does rigor mortis characteristically appear first?', 'rigor-mortis-mcq', 'third-professional-mbbs', 'Rigor follows Nysten''s law: it begins in the small muscles of the eyelids, face and jaw, then descends through the neck, trunk and arms to the legs, and passes off in the same order. Onset is hastened by heat, exercise before death and low muscle mass, and delayed by cold. The key distractor, beginning in the large limb muscles, is the common misconception; cardiac muscle is the first muscle of the body to become rigid but is not part of the visible skeletal sequence.', 'published',
  (SELECT id FROM subjects WHERE slug = 'forensic-medicine'), (SELECT t.id FROM topics t WHERE t.slug = 'identification' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'forensic-medicine')), 'easy', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'A', 'The small muscles of the eyelids, face and jaw, spreading downward to the limbs', 1, 0 FROM mcqs WHERE slug = 'rigor-mortis-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'The large muscles of the thighs and buttocks, spreading upward to the face', 0, 1 FROM mcqs WHERE slug = 'rigor-mortis-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'The myocardium first, followed by all skeletal muscles simultaneously', 0, 2 FROM mcqs WHERE slug = 'rigor-mortis-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', 'All skeletal muscles of the body at the same moment', 0, 3 FROM mcqs WHERE slug = 'rigor-mortis-mcq';
