INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'A screening test for a disease has 100% sensitivity but poor specificity. What can be concluded when the test result is negative?', 'sensitivity-mcq', 'third-professional-mbbs', 'Sensitivity is the proportion of true diseased people who test positive, TP/(TP+FN); at 100% sensitivity there are no false negatives, so a negative result cannot belong to a diseased person — the rule taught as SnNout, a sensitive test with a Negative result rules the disease out. The key distractor reverses the roles: specificity governs the positive result (SpPin), and prevalence governs the predictive values of a positive test, not the sensitivity itself.', 'published',
  (SELECT id FROM subjects WHERE slug = 'community-medicine'), (SELECT t.id FROM topics t WHERE t.slug = 'biostatistics' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'community-medicine')), 'medium', '["diagnostic-test-accuracy"]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'A', 'The disease is effectively ruled out, because a highly sensitive test has very few false negatives', 1, 0 FROM mcqs WHERE slug = 'sensitivity-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'The disease is confirmed, because sensitivity measures the true positive rate', 0, 1 FROM mcqs WHERE slug = 'sensitivity-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'Nothing can be concluded, because only specificity determines the meaning of a negative result', 0, 2 FROM mcqs WHERE slug = 'sensitivity-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', 'The conclusion depends mainly on the prevalence of the disease in the screened population', 0, 3 FROM mcqs WHERE slug = 'sensitivity-mcq';
