INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'A 55-year-old smoker undergoes spirometry. The FEV1 is 62% of predicted, the FVC is 58% of predicted, and the FEV1/FVC ratio is 0.95. Which pattern of lung disease do these results best fit?', 'spirometry-fev1-mcq', 'first-professional-mbbs', 'The defining datum is the FEV1/FVC ratio of 0.95, which is normal to high. Obstruction is defined by a reduced ratio (below about 0.7), because narrowed airways slow expiratory flow out of proportion to the volume exhaled; here FEV1 and FVC have fallen roughly in proportion, which is the signature of stiff, restricted lungs such as pulmonary fibrosis. The key distractor, obstructive disease, is excluded precisely because the ratio is preserved — in pure obstruction the FVC is relatively maintained while the FEV1 falls disproportionately.', 'published',
  (SELECT id FROM subjects WHERE slug = 'physiology'), (SELECT t.id FROM topics t WHERE t.slug = 'respiratory' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'physiology')), 'hard', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'A', 'Restrictive disease, with both volumes reduced but the ratio preserved or increased', 1, 0 FROM mcqs WHERE slug = 'spirometry-fev1-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'Obstructive disease, with air trapping lowering the FEV1/FVC ratio', 0, 1 FROM mcqs WHERE slug = 'spirometry-fev1-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'Mixed obstructive and restrictive disease', 0, 2 FROM mcqs WHERE slug = 'spirometry-fev1-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', 'Normal spirometry with an isolated reduction of the FVC', 0, 3 FROM mcqs WHERE slug = 'spirometry-fev1-mcq';
