INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'At the venous end of a systemic capillary, which Starling force is the principal driver pulling fluid back from the interstitium into the vessel lumen?', 'starling-forces-mcq', 'first-professional-mbbs', 'Along the capillary, hydrostatic pressure falls from roughly 30 to about 15 mmHg while plasma oncotic pressure stays near 28 mmHg, so at the venous end the inward oncotic force dominates and fluid is reabsorbed. The key distractor, capillary hydrostatic pressure, acts in the opposite direction — it pushes fluid out of the vessel, which is why raised venous pressure causes oedema rather than reabsorption. Albumin matters most because it is abundant and too large to filter freely, so it sustains the osmotic gradient.', 'published',
  (SELECT id FROM subjects WHERE slug = 'physiology'), (SELECT t.id FROM topics t WHERE t.slug = 'cardiovascular' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'physiology')), 'medium', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'A', 'Capillary hydrostatic pressure generated by arterial pressure', 0, 0 FROM mcqs WHERE slug = 'starling-forces-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'Interstitial fluid hydrostatic pressure', 0, 1 FROM mcqs WHERE slug = 'starling-forces-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'Plasma colloid osmotic (oncotic) pressure, generated mainly by albumin', 1, 2 FROM mcqs WHERE slug = 'starling-forces-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', 'Interstitial fluid colloid osmotic pressure from filtered plasma proteins', 0, 3 FROM mcqs WHERE slug = 'starling-forces-mcq';
