INSERT INTO mcqs (question, slug, level, explanation, status, subject_id, topic_id, difficulty, tags_json, created_by, created_at, updated_at)
VALUES (
  'Which enzyme catalyses the committed, rate-limiting step of the urea cycle, and what is its obligatory activator?', 'urea-cycle-mcq', 'first-professional-mbbs', 'Carbamoyl phosphate synthetase I sits in the mitochondrial matrix, condenses ammonia with bicarbonate using two ATP, and is switched on by N-acetylglutamate, whose own synthesis rises after a protein meal — the classic feed-forward control that matches urea production to the nitrogen load. The key distractor, ornithine transcarbamylase, is the second mitochondrial step and its deficiency is the most common inherited urea-cycle defect, but it is not rate-limiting; arginase merely hydrolyses arginine in the final step.', 'published',
  (SELECT id FROM subjects WHERE slug = 'biochemistry'), (SELECT t.id FROM topics t WHERE t.slug = 'biomolecules' AND t.subject_id = (SELECT id FROM subjects WHERE slug = 'biochemistry')), 'hard', '[]',
  (SELECT id FROM users ORDER BY id LIMIT 1), '2026-09-06 09:00:00', '2026-09-06 09:00:00'
);
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'A', 'Carbamoyl phosphate synthetase I, activated by N-acetylglutamate', 1, 0 FROM mcqs WHERE slug = 'urea-cycle-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'B', 'Ornithine transcarbamylase, activated by ornithine', 0, 1 FROM mcqs WHERE slug = 'urea-cycle-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'C', 'Argininosuccinate synthetase, activated by citrulline', 0, 2 FROM mcqs WHERE slug = 'urea-cycle-mcq';
INSERT INTO mcq_options (mcq_id, label, text, is_correct, sort_order)
SELECT id, 'D', 'Arginase, activated by aspartate', 0, 3 FROM mcqs WHERE slug = 'urea-cycle-mcq';
